SELECT T1.objid, T2.ra, T2.dec 
FROM photoobj AS T1 INNER JOIN specobj AS T2 ON T1.bestobjid = T2.bestobjid 
WHERE T2.survey = 'Galaxy' AND T2.specobjid IN ( SELECT specobjid FROM spplines );

SELECT T1.z, T2.ra, T2.dec 
FROM specobj AS T1 INNER JOIN photoobj AS T2 ON T1.bestobjid = T2.objid 
WHERE T1.class LIKE '%Starforming Galaxy%' AND T2.type = 3;

SELECT T2.objid, T2.ra, T2.dec 
FROM specobj AS T1 INNER JOIN photoobj AS T2 ON T1.bestobjid = T2.objid 
WHERE T1.class LIKE '%GALAXY%' AND T1.subclass LIKE 'EMLINE';

SELECT T2.objid, T2.ra, T2.dec 
FROM specobj AS T1 INNER JOIN photoobj AS T2 ON T1.bestobjid = T2.objid 
WHERE T1.class LIKE '%GALAXY%' AND T1.subclass LIKE 'EMLINE%';

SELECT T1.gene_symbol, T2.pvalue 
FROM differential_expression AS T1 INNER JOIN disease AS T2 ON T1.doid = T2.id 
WHERE T1.gene_symbol = 'EGFR' AND T2.name = 'lung cancer';

